     and a.bill_id = #{billId}
     and a.usage_id = #{usageId}
     and a.diff_type = #{diffType}
     and a.handle_status = #{handleStatus}
     and a.supplier_id = #{supplierId}
     and a.customer_id = #{customerId}
     and a.call_no like concat('%', #{callNo}, '%')

        and a.call_time >= (case when char_length(#{params.beginTime}) <= 10
                                   then concat(#{params.beginTime}, ' 00:00:00') else #{params.beginTime} end)


        and a.call_time <= (case when char_length(#{params.endTime}) <= 10
                                   then concat(#{params.endTime}, ' 23:59:59') else #{params.endTime} end)


        and a.supplier_id in

            #{scopeSupplierId}



order by a.handle_status, a.call_time desc, a.id desc

